using System;using System.Linq;using System.IO;using Verse;using Verse.AI;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){foreach(var d in Find.WindowStack.Windows.OfType<Dialog_MiniGame>().ToList())d.Close();TogetherMatch.Reset();var b=(Thing)Host.State["chess"];var p=(Pawn)Host.State["rostra"];var o=(Pawn)Host.State["anya"];var s=GameComponent_Recreation.Current.SessionFor(b);if(s!=null)GameComponent_Recreation.Current.Remove(s);foreach(var x in new[]{p,o}){x.drafter.Drafted=false;x.jobs.EndCurrentJob(JobCondition.InterruptForced);x.needs.food.CurLevelPercentage=1;x.needs.rest.CurLevelPercentage=1;}GameEntry.Commit(b.TryGetComp<CompMiniGame>().Game,b,p,o,2,false);int stage=0,start=Find.TickManager.TicksGame;string log=Host.Root+"/resume-exact.txt";File.WriteAllText(log,"Using furniture CompFloatMenuOptions resume action.\n");Host.Watch=()=>{int t=Find.TickManager.TicksGame;var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(stage==0&&d!=null){File.AppendAllText(log,"live jobs="+p.CurJobDef+","+o.CurJobDef+"\n");o.drafter.Drafted=true;stage=1;start=t;}else if(stage==1&&(d==null||t-start>180)){File.AppendAllText(log,"drafted closed="+(d==null)+" ticks="+(t-start)+" stored="+(GameComponent_Recreation.Current.SessionFor(b)!=null)+"\n");var opt=b.TryGetComp<CompMiniGame>().CompFloatMenuOptions(p).First();opt.action();File.AppendAllText(log,"ACTUAL RESUME label="+opt.Label+" immediateWindow="+Find.WindowStack.Windows.Any(w=>w is Dialog_MiniGame)+" drafted="+o.Drafted+" jobs="+p.CurJobDef+","+o.CurJobDef+"\n");stage=2;start=t;}else if(stage==2&&t-start>120){File.AppendAllText(log,"after120 window="+(d!=null)+" stored="+(GameComponent_Recreation.Current.SessionFor(b)!=null)+" jobs="+p.CurJobDef+","+o.CurJobDef+"\n");Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.Watch=null;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return "Testing exact UI resume action while opponent is drafted.";}}
